import torch
import torch.nn as nn
import math
from torch.utils.cpp_extension import load_inline

# Custom CUDA kernels for ConvTranspose3d+Scale and fused MaxPool+GlobalAvg+Clamp
conv_transpose_scale_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void conv_transpose_scale_kernel(
    const float* input,
    const float* weight,
    const float* bias,
    float* output,
    int batch_size,
    int in_channels,
    int out_channels,
    int input_depth,
    int input_height,
    int input_width,
    int kernel_size,
    int stride,
    int padding,
    int output_depth,
    int output_height,
    int output_width,
    float scale
) {
    int b = blockIdx.x;
    int c_out = blockIdx.y;
    int z = blockIdx.z / (output_height * output_width);
    int y = (blockIdx.z % (output_height * output_width)) / output_width;
    int x = blockIdx.z % output_width;

    if (b >= batch_size || c_out >= out_channels || z >= output_depth || y >= output_height || x >= output_width) return;

    float val = 0.0f;

    for (int c_in = 0; c_in < in_channels; ++c_in) {
        for (int kz = 0; kz < kernel_size; ++kz) {
            for (int ky = 0; ky < kernel_size; ++ky) {
                for (int kx = 0; kx < kernel_size; ++kx) {
                    int input_z = (z - kz + padding) / stride;
                    int input_y = (y - ky + padding) / stride;
                    int input_x = (x - kx + padding) / stride;

                    if ((z - kz + padding) % stride != 0 || (y - ky + padding) % stride != 0 || (x - kx + padding) % stride != 0) 
                        continue;

                    if (input_z >=0 && input_z < input_depth && input_y >=0 && input_y < input_height && input_x >=0 && input_x < input_width) {
                        int input_idx = b * in_channels * input_depth * input_height * input_width +
                                      c_in * input_depth * input_height * input_width +
                                      input_z * input_height * input_width +
                                      input_y * input_width +
                                      input_x;

                        int weight_idx = c_out * in_channels * kernel_size * kernel_size * kernel_size +
                                       c_in * kernel_size * kernel_size * kernel_size +
                                       kz * kernel_size * kernel_size +
                                       ky * kernel_size +
                                       kx;

                        val += input[input_idx] * weight[weight_idx];
                    }
                }
            }
        }
    }

    if (bias != nullptr) {
        val += bias[c_out];
    }

    val *= scale;

    int output_idx = b * out_channels * output_depth * output_height * output_width +
                   c_out * output_depth * output_height * output_width +
                   z * output_height * output_width +
                   y * output_width +
                   x;
    output[output_idx] = val;
}

torch::Tensor conv_transpose_scale_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int padding,
    float scale
) {
    auto batch_size = input.size(0);
    int in_channels = input.size(1);
    int input_depth = input.size(2);
    int input_height = input.size(3);
    int input_width = input.size(4);
    int out_channels = weight.size(0);
    int kernel_size = weight.size(2);

    int output_depth = (input_depth - 1) * stride + kernel_size - 2 * padding;
    int output_height = (input_height - 1) * stride + kernel_size - 2 * padding;
    int output_width = (input_width - 1) * stride + kernel_size - 2 * padding;

    auto output = torch::zeros({batch_size, out_channels, output_depth, output_height, output_width}, input.options());

    dim3 blocks(batch_size, out_channels, output_depth * output_height * output_width);
    conv_transpose_scale_kernel<<<blocks, 1>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        in_channels,
        out_channels,
        input_depth,
        input_height,
        input_width,
        kernel_size,
        stride,
        padding,
        output_depth,
        output_height,
        output_width,
        scale
    );

    return output;
}

__global__ void fused_pool_clamp_kernel(
    const float* input,
    float* output,
    int batch_size,
    int channels,
    int depth,
    int height,
    int width,
    int pool_kernel,
    float clamp_min,
    float clamp_max
) {
    int b = blockIdx.x / channels;
    int c = blockIdx.x % channels;

    if (b >= batch_size || c >= channels) return;

    int num_windows_z = depth / pool_kernel;
    int num_windows_y = height / pool_kernel;
    int num_windows_x = width / pool_kernel;
    int total_windows = num_windows_z * num_windows_y * num_windows_x;

    float sum = 0.0f;

    for (int wz = 0; wz < num_windows_z; ++wz) {
        for (int wy = 0; wy < num_windows_y; ++wy) {
            for (int wx = 0; wx < num_windows_x; ++wx) {
                float max_val = -FLT_MAX;
                for (int dz = 0; dz < pool_kernel; ++dz) {
                    for (int dy = 0; dy < pool_kernel; ++dy) {
                        for (int dx = 0; dx < pool_kernel; ++dx) {
                            int z = wz * pool_kernel + dz;
                            int y = wy * pool_kernel + dy;
                            int x = wx * pool_kernel + dx;
                            if (z < depth && y < height && x < width) {
                                int idx = b * channels * depth * height * width +
                                        c * depth * height * width +
                                        z * height * width +
                                        y * width +
                                        x;
                                max_val = fmaxf(max_val, input[idx]);
                            }
                        }
                    }
                }
                sum += max_val;
            }
        }
    }

    float avg = sum / total_windows;
    avg = fminf(fmaxf(avg, clamp_min), clamp_max);

    output[b * channels + c] = avg;
}

torch::Tensor fused_pool_clamp_cuda(
    torch::Tensor input,
    int pool_kernel,
    float clamp_min,
    float clamp_max
) {
    auto batch_size = input.size(0);
    int channels = input.size(1);
    int depth = input.size(2);
    int height = input.size(3);
    int width = input.size(4);

    auto output = torch::zeros({batch_size, channels, 1, 1, 1}, input.options());

    dim3 blocks(batch_size * channels);
    fused_pool_clamp_kernel<<<blocks, 1>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        channels,
        depth,
        height,
        width,
        pool_kernel,
        clamp_min,
        clamp_max
    );

    return output;
}
"""

conv_transpose_scale_cpp = """
torch::Tensor conv_transpose_scale_cuda(torch::Tensor input, torch::Tensor weight, torch::Tensor bias, int stride, int padding, float scale);
torch::Tensor fused_pool_clamp_cuda(torch::Tensor input, int pool_kernel, float clamp_min, float clamp_max);
"""

custom_ops = load_inline(
    name='custom_ops',
    cpp_sources=conv_transpose_scale_cpp,
    cuda_sources=conv_transpose_scale_source,
    functions=['conv_transpose_scale_cuda', 'fused_pool_clamp_cuda'],
    verbose=False
)

class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, stride, padding, scale, maxpool_kernel_size):
        super(ModelNew, self).__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.scale = scale
        self.maxpool_kernel_size = maxpool_kernel_size
        self.clamp_min = 0
        self.clamp_max = 1

        # Initialize weights and bias for transposed convolution
        self.weight = nn.Parameter(torch.Tensor(
            out_channels, in_channels, kernel_size, kernel_size, kernel_size
        ))
        self.bias = nn.Parameter(torch.Tensor(out_channels))

        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        fan_in, _ = nn.init._calculate_fan_in_and_fan_out(self.weight)
        bound = 1 / math.sqrt(fan_in)
        nn.init.uniform_(self.bias, -bound, bound)

    def forward(self, x):
        # Custom ConvTranspose3d + Scale
        x = custom_ops.conv_transpose_scale_cuda(
            x, 
            self.weight, 
            self.bias,
            self.stride,
            self.padding,
            self.scale
        )

        # Fused MaxPool + GlobalAvgPool + Clamp
        x = custom_ops.fused_pool_clamp_cuda(
            x,
            self.maxpool_kernel_size,
            self.clamp_min,
            self.clamp_max
        )

        return x
